def solve():
    import itertools
    for p in itertools.permutations(range(5)):
        if p[2] != 3:
            continue
        valid = True
        for d in range(1, 5):
            diffs = set()
            for i in range(5 - d):
                diff = p[i+d] - p[i]
                if diff in diffs:
                    valid = False
                    break
                diffs.add(diff)
            if not valid:
                break
        if valid:
            print(list(p))
            return

solve()
